export const COMMON_EVIDENCE='Gemeinsamer Stückablauf: Ein Terrorist hatte die Passagiermaschine entführt und wollte sie in das mit 70 000 Menschen besetzte Stadion steuern. Koch schoss das entführte Passagierflugzeug ab. Dabei wurden die 164 Menschen an Bord getötet. Mit dem Abschuss wollte er die 70 000 Menschen im Stadion retten. Meisers Mann gehörte zu den Menschen an Bord. Koch ist der Angeklagte, Nelson die Anklägerin und Biegler sein Verteidiger; die lesende Person im Chat ist keine dieser Figuren.';
export const sourceFor=(id,question='')=>COMMON_EVIDENCE+' '+(TEXT_EVIDENCE[id]||'')+(id==='biegler'&&/notwehr/i.test(question)?' Ergänzende Begriffsquelle § 32 StGB: Notwehr ist die erforderliche und gebotene Verteidigung gegen einen gegenwärtigen rechtswidrigen Angriff.':'' );
const norm=s=>s.normalize('NFKC').toLowerCase().replace(/ß/g,'ss');
export function requirementsFor(id,question){
 const q=norm(question),r=[];
 if(id==='nelson'&&/strafbar|verurteilen|anklage/.test(q))r.push('Erkläre Nelsons rechtlichen Einwand gegen die Tötung Unschuldiger. Eine im Fragetext schon genannte Rettungsabsicht ist die Prämisse, keine gesonderte Frage nach Kochs Motivation.');
 if(!['koch','meiser'].includes(id)&&/familie|privat|eigenes? kind|kinder|verheiratet/.test(q)&&/was wissen|wissen wir|über.*familie|belegt|im stück|überhaupt|haben sie/.test(q))r.push('Beantworte die Familienfrage als Textfrage: Das Stück nennt hierzu keine gesicherten Angaben. Nicht behaupten, die Figur wisse selbst nicht, ob sie Kinder habe. Ein angenommenes Kind bleibt hypothetisch.');
 if(id==='nelson'&&/zusehen|beim sterben/.test(q))r.push('Unterscheide fortbestehende Schutzpflicht im Stadion und Grenzen der Tötung Unschuldiger. Kein falsches Entweder-oder und keine erfundenen konkreten Einsatzpläne.');
 if(id==='biegler'&&/abschuss/.test(q)&&/bestreit/.test(q))r.push('Trenne den unstrittigen Abschuss von der individuellen Strafbarkeit. Biegler verteidigt die Rettungsabwägung als kleineres Übel. Beantworte, welche rechtliche Bewertung noch strittig ist.');
 if(id==='biegler'&&/notwehr/.test(q))r.push('Rechtsbegriff aus § 32 StGB (gesetze-im-internet.de/stgb/__32.html): Notwehr betrifft die erforderliche und gebotene Verteidigung gegen einen gegenwärtigen rechtswidrigen Angriff. Eine behauptete Rechtfertigung erbringt diesen Nachweis nicht. Im Plädoyer verteidigt Biegler die Rettungsabwägung und das kleinere Übel; eine Notwehrbegründung ist dort nicht gegeben. Antworte auf die Beweisfrage, statt eine ungesicherte Gesetzesdefinition hinzuzufügen.');
 if(id==='biegler'&&/freispruch|164|anklage/.test(q))r.push('Erkläre das Rettungsziel und den Einwand gegen das Vorranggeben abstrakter Prinzipien. Nicht nur die eigene Rolle nennen. Tat und individuelle Strafbarkeit unterscheiden.');
 if(id==='biegler'&&/verfassung|gesetz|notwehr|rechtfertig/.test(q))r.push('Kein bereits bewiesener Rechtfertigungsgrund. Die Verfassungswidrigkeit des Gesetzes ist von der individuellen Strafbarkeit zu unterscheiden; keine erfundenen Rechtsbegriffe.');
 if(id==='meiser'&&/sms|nachricht/.test(q))r.push('SMS: Mann bereits im Flugzeug, Versuch zum Cockpit/Pilotenraum. Die Begriffe nicht vertauschen. Quelle ist die Nachricht, nicht eigene Beobachtung an Bord.');
 if(id==='meiser'&&/hätte|wäre|gelungen|sicher überlebt/.test(q))r.push('Nimm den im Gedankenexperiment unterstellten Cockpit-Zutritt an. Er garantiert kein Überleben. Trenne hypothetischen Ausgang, damalige Nachricht und später feststehenden Tod. Nicht auf die Frage ausweichen, ob der Zutritt tatsächlich gelang.');
 if(id==='meiser'&&/wie alt|alter/.test(q)&&/tochter|kind/.test(q))r.push('Alter der Tochter im Stück: sieben Jahre.');
 if(id==='lauterbach'&&/vorgesetz|dienstgrad|verantwort|anweis|befehl/.test(q))r.push('Oberstleutnant, Duty Controller, Befehlsweitergabe von Generalleutnant Radtke. Nicht der Abschusspilot. Keine unbelegte kategorische Aussage über eine disziplinarische Vorgesetztenstellung.');
 if(id==='vorsitz'&&/publikum|schöff|zuschau|abstimm|entscheidung|entscheiden/.test(q))r.push('Das Abstimmungsergebnis des Publikums bestimmt die verkündete Urteilsfassung. Vorsitzender verkündet, Publikum entscheidet in dieser Theaterkonstruktion. Nicht bloss gesellschaftliche Reflexion.');
 if(id==='vorsitz'&&/fassung|freispruch|verurteil|ende|alternativ/.test(q))r.push('Zwei im Text vorhandene alternative Fassungen; pro Aufführung eine je nach Abstimmung. Keine Abfolge zweier Prozesse und keine Behauptung, es gebe nach Freispruch keine zweite Textfassung.');
 return r;
}
export function sourceIssues(id,question,answer,context=''){
 const q=norm(question),s=norm(answer),issues=[];
 if(id==='nelson'&&/kind|angehörig/.test(q)&&/wenn|angenommen/.test(q)&&!/cockpit|flugzeug|bord/.test(q)&&(/stadion/.test(q)||(/dort/.test(q)&&/stadion/.test(norm(context))))&&/mein(?:e|en|em)? (?:sohn|kind|tochter).{0,35}(?:cockpit|flugzeug|bord)/.test(s))issues.push('Die hypothetische Prämisse wurde verändert: Das angenommene Kind ist im Stadion, nicht im Cockpit/Flugzeug. Auf genau diese Prämisse antworten, ohne den Ort oder die betroffene Person auszutauschen.');
 if(/(?:tötung|tod|getötet|toten)[^.!?;]{0,30}164[^.!?;]{0,45}im stadion|164[^.!?;]{0,35}(?:getötete|unschuldige|opfer|menschen)[^.!?;]{0,18}im stadion/.test(s)&&!/164.{0,35}nicht im stadion/.test(s))issues.push('Opfer und Orte vertauscht: Die 164 Menschen wurden im Flugzeug getötet. Koch wollte die 70 000 Menschen im Stadion retten.');

 if([...s.matchAll(/(?:terrorist|entführer|lauterbach|radtke)\s+(?:hat|hatte|hätte|habe)\b([^.!?]{0,55})(?:flugzeug|maschine)([^.!?]{0,25})abgeschossen/g)].some(m=>!/koch|berichtet|gemeldet|gesagt|mitgeteilt|bestätigt|erfahren|nicht/.test(m[1]+m[2])))issues.push('Falscher Akteur: Koch schoss die Passagiermaschine ab, nicht der Terrorist, Lauterbach oder Radtke. Auch beim Gedankenexperiment über einen Cockpit-Zutritt den Abschusspiloten nicht austauschen.');
 if(!['koch','meiser'].includes(id)&&/mein(?:e|en|em|er)? (?:sohn|tochter)/.test(s)&&!(/wenn|angenommen|hätte|hypothetisch/.test(norm(question+' '+context))&&/kind|sohn|tochter|angehörig/.test(norm(question+' '+context))))issues.push('Keine private Familie erfinden. Ein eigener Sohn oder eine eigene Tochter ist für diese Figur nicht belegt. Nur ein ausdrücklich erfragtes Gedankenexperiment erlaubt hypothetische Angehörige; keine unaufgeforderte Erklärung an erfundene Kinder.');
 if(id==='nelson'&&s.split(/[.!?]/).some(t=>/es geht darum[^;]{0,35}(?:balance|abwägung) zwischen schutz und (?:der )?tötung[^;]{0,25}(?:finden|herstellen|suchen|erreichen)/.test(t)&&!/nicht|biegler/.test(t)))issues.push('Nelsons Position verlangt Schutz innerhalb von Recht und Menschenwürde, ohne unschuldige Leben zu verrechnen. Die Tötung der Passagiere wird damit nicht zu einer erlaubten Schutzmassnahme.');
 if(id==='biegler'&&/abschuss/.test(q)&&/bestreit/.test(q)&&/strafrechtlich relevant/.test(s)&&!/strafbar|strafbarkeit|\bschuld\b|schuldfäh|rechtliche bewertung|strafrechtlich verantwortlich/.test(s))issues.push('Benenne die strittige individuelle Strafbarkeit oder strafrechtliche Verantwortlichkeit präzise. Der Abschuss und die Tötung der 164 Menschen sind unstrittig; zu prüfen ist, ob Koch sich strafbar gemacht hat.');
 const stagedAddress=/antworte.{0,25}(?:direkt|wörtlich).{0,35}(?:koch|tochter)|sprich.{0,20}(?:koch|tochter).{0,20}an/.test(q);
 if(!stagedAddress&&id!=='koch'&&/ihre(?:r|n|m|s)? (?:tat|handlung|rettungsabsicht|entscheidung zum abschuss|verurteilung|freispruch)|sie (?:eine )?rettungsabsicht|sie[^.!?]{0,80}(?:retten wollten|getötet haben|abgeschossen haben)|sie haben.{0,45}(?:kleinere übel|abgeschossen|getötet)|sie (?:unter|aus) extrem/.test(s))issues.push('Rollenverwechslung: Das Gegenüber ist eine lesende Person, nicht Koch. Kochs Tat/Handlung/Entscheidung in der dritten Person nennen. Keine eigenen oder fremden Taten dem Gegenüber zuschreiben.');
 if(!stagedAddress&&id==='meiser'&&/\b(?:ihr|dein)(?:e|en|em|es|er)? (?:vater|papa|mann|tochter|mutter|mama)/.test(s)&&!(/tochter/.test(q)&&/erklär|sag/.test(q)&&/ich (?:würde|könnte)[^.!?]{0,45}(?:meiner|der) tochter[^.!?]{0,30}(?:sagen|erklären)/.test(s)))issues.push('Meiser spricht mit Lesenden, nicht mit ihrer Tochter. Eigene Beziehungen mit mein Mann/meine Tochter benennen; eine Erklärung an die Tochter indirekt formulieren.');
 if(id==='biegler'&&/bestreite.{0,80}bewertung als (?:gerechtfertigt|rechtfertigend)|entschuldigend.{0,35}nicht als straflos|statt 164 zu töten/.test(s))issues.push('Die Formulierung verdreht Bieglers Verteidigung: Er bestreitet die Strafbarkeit, nicht die Rechtfertigung; tatsächlich wurden 164 Menschen getötet. Eine Entschuldigung ist kein Beweis fortbestehender Strafbarkeit. Keine juristische Kategorie als bereits festgestellt behaupten.');

 if(id!=='koch'&&/^koch\b/.test(q)&&!/sagen|vorwerfen|ansprechen/.test(q)&&/ihre rettungsabsicht|ihre entscheidung zum abschuss|sie haben.{0,25}abgeschossen/.test(s))issues.push('Das fragende Gegenüber ist nicht Koch. Die Frage handelt von Kochs Rettungsabsicht bzw. Entscheidung; diese nicht den Lesenden zuschreiben.');
 if(/darf keine.{0,35}(?:menschen|leben).{0,50}als mittel.{0,60}retten/.test(s))issues.push('Der Satz vertauscht Retten und Opfern: Es geht um das Verbot, Unschuldige zur Rettung anderer zu töten, nicht um ein Verbot, Unschuldige zu retten.');
 if(!['koch','meiser'].includes(id)&&/kann (?:daher )?nicht bestätigen,? ob ich kinder|nicht bestätigen kann,? ob ich kinder|(?:ich weiss nicht|weiss ich nicht),? ob ich kinder/.test(s))issues.push('Keine autobiografische Amnesie behaupten. Die Textgrundlage nennt keine gesicherten Familienangaben; das ist keine Unwissenheit der Figur über das eigene Leben.');

 if(/menschenleben.{0,20}(?:tötete|getötet)|(?:tötete|getötet).{0,15}menschenleben/.test(s))issues.push('Sprachfehler: Menschen werden getötet, Menschenleben werden ausgelöscht oder gehen verloren. Formuliere idiomatisch, ohne den Sinn zu ändern.');
 if(/\brechtfertigt ist\b|den tod zusehen|sein ziel retten war|entmündigung der rechte|die nicht rechtfertigt|ich richte (?:angeklag|zeugen|das publikum)|sondern allein auf der basis[.!]|ich lasse weder freispruch noch verurteilung vor|das meine position nicht|leben aufzählen|nicht kochs vorgesetzter,? noch/.test(s))issues.push('Unidiomatischer oder unvollständiger deutscher Satz. Klare Verben und vollständige Bezüge; weder ... noch statt nicht ... noch.');
 if(!['koch','meiser'].includes(id)&&requirementsFor(id,question).some(r=>r.startsWith('Beantworte die Familienfrage'))&&!/nicht.{0,40}(?:belegt|bekannt|genannt|beschrieben|ausgeführt|erwähnt|überliefert)|keine.{0,55}(?:angaben|informationen|aussagen|details)|(?:stück|text).{0,35}(?:äussert|sagt|erzählt|verrät).{0,30}nicht|bleibt.{0,35}unerwähnt|privatleben.{0,40}(?:offen|unbekannt)|(?:stück|text).{0,55}nichts/.test(s))issues.push('Die Teilfrage nach den belegten privaten Familienangaben fehlt. Dazu nennt das Stück hier keine gesicherten Angaben.');
 if(id==='biegler'){
  if(/vermeintlich[^.!?]{0,25}(?:verlust|tod)[^.!?]{0,30}164/.test(s))issues.push('Die 164 Menschen wurden tatsächlich getötet. Biegler bestreitet die Todesopfer nicht; strittig sind Strafbarkeit und Rettungsabwägung.');
  if(/(?:möglicherweise|vielleicht|eventuell) rechtfertigt in (?:dieser|der) (?:extremen )?situation[.!?]?$/.test(s))issues.push('Die Formulierung ist grammatisch unvollständig; das Partizip lautet gerechtfertigt. Aussage und Unsicherheitsgrad beibehalten.');
  if(/abschuss/.test(q)&&/bestreit/.test(q)&&/tatbestand der notwehr[^.!?]{0,20}bestreit/.test(s))issues.push('Gefragt ist die noch strittige Bewertung des eingeräumten Abschusses: individuelle Strafbarkeit und Rettungsabwägung. Biegler nicht einen bestrittenen Notwehrtatbestand als belegte Plädoyerposition zuschreiben.');
  if(/einwand.*anklage/.test(q)&&s.split(/[.!?]/).some(t=>/anklage[^;]{0,30}fokussiert(?: sich)? auf (?:die )?(?:zahl|opferzahl)|anklage[^;]{0,30}nur[^;]{0,15}opferzahl/.test(t)&&!/nicht nur|anklage[^;]{0,40}nicht|nicht[^;]{0,20}anklage/.test(t)))issues.push('Nelsons Einwand ist das gleiche Lebensrecht und die Menschenwürde jedes Einzelnen, nicht bloss die Opferzahl. Beantworte diesen Einwand aus Bieglers Rettungsabwägung.');
  if(/notwehr/.test(q)&&/voraussetzungen der notwehr[^.!?]{0,150}(?:drohende gefahr|verhältnismässig)/.test(s)&&!/gegenwärtig[^.!?]{0,50}angriff/.test(s)&&!/voraussetzungen der notwehr[^.!?]{0,50}nicht/.test(s))issues.push('Bei einer Notwehrdefinition den Kern von § 32 StGB präzise nennen: erforderliche und gebotene Verteidigung gegen einen gegenwärtigen rechtswidrigen Angriff. Eine allgemeine Gefahren- oder Verhältnismässigkeitsformel ist kein Nachweis.');
  if(s.split(/[.!?]/).some(t=>/kein(?:en)? (?:gegenwärtigen? )?angriff|kein angriff durch einen dritten/.test(t)&&!/\b(?:wenn|falls|hätte|hätten|wäre|wären|würde|würden|angenommen)\b/.test(t)))issues.push('Den terroristischen Angriff nicht verneinen: Die Maschine war entführt und auf das Stadion gerichtet. Die Prüfung von Rechtfertigung/Entschuldigung ist strittig; das blosse Behaupten einer Rechtfertigung beweist keine Notwehr.');
  if(/verfassungssicherheit|verfassungsrechtlichen? schutzvorschriften|nicht um schuld/.test(s))issues.push('Die juristische Formulierung ist nicht sauber textgestützt. Erkläre Rettungsziel, Verfassungswidrigkeit des Gesetzes und davon getrennte individuelle Strafbarkeit; keine erfundenen Schutzkategorien.');
  if(/freispruch/.test(q)&&/164|getötet|anklage/.test(q)&&!/rett|stadion|70[ .]?000|siebzigtausend/.test(s))issues.push('Die konkrete Begründung des Freispruchsantrags fehlt: das Rettungsziel im Stadion und die extreme Abwägung, nicht nur abstrakte Strafbarkeitsfloskeln.');
 }
 if(id==='meiser'){
  if(/sms|nachricht/.test(q+s)&&!/wenn|hätte|gelungen/.test(q)&&/beweist[^.!?]{0,60}(?:er|mein mann)[^.!?]{0,20}im cockpit war|(?:er|mein mann) (?:war|befand sich) (?:bereits )?im cockpit|den piloten zu helfen/.test(s)&&!/nicht[^.!?]{0,70}im cockpit war/.test(s))issues.push('Die SMS meldet einen Versuch, ins Cockpit zu kommen. Sie beweist weder den Zutritt noch ein Helfen bei den Piloten. Versuch und Erfolg sauber trennen; keine Tätigkeit im Cockpit hinzuerfinden.');
  if(/(?:versuch\w*|wollte).{0,70}(?:ins|in das) (?:passagier)?flugzeug|versuch\w*.{0,50}an bord (?:zu )?(?:kommen|gelangen|gehen)/.test(s))issues.push('Falscher Ort: Ihr Mann war bereits im Flugzeug; der berichtete Versuch galt dem Cockpit/Pilotenraum.');
  if(/sms|nachricht/.test(q)&&/beweist|belegen|beweist|was.*nicht|letzte/.test(q)&&!/cockpit|piloten(?:kanzel|raum|kabine)|raum der piloten/.test(s))issues.push('Die Antwort nennt den konkreten Inhalt der SMS nicht: Versuch, ins Cockpit bzw. den Raum der Piloten zu gelangen.');
  if(/(?:hätte|wäre|wenn).*(?:überlebt|gerettet)|sicher überlebt/.test(q)&&!/wäre|hätte|auch dann|selbst bei|unter dieser annahme|allein|erfolgreich|gelungen/.test(s))issues.push('Die Gegenhypothese wird nicht beantwortet: Unterstelle für die Antwort den gelungenen Cockpit-Zutritt und erläutere, warum daraus kein sicheres Überleben folgt.');
  if(/ob er verletzt oder getötet wurde|unklar.{0,25}ob (?:mein mann|er).{0,25}(?:tot|getötet|gestorben)/.test(s))issues.push('Der tatsächliche Tod ihres Mannes steht fest. Nicht mit der offenen Frage nach einem anderen hypothetischen Verlauf vermischen.');
  if(/wie alt|alter/.test(q)&&/tochter|kind/.test(q)&&!/\b7\b|sieben/.test(s))issues.push('Die Altersfrage ist nicht beantwortet: Die Tochter ist im Stück sieben Jahre alt.');
 }
 if(id==='lauterbach'&&/vorgesetz|befehl|anweis/.test(q)){
  if(/ich bin (?:nicht )?kochs vorgesetzter|ich war (?:nicht )?sein vorgesetzter/.test(s))issues.push('Kein unbelegtes pauschales Ja/Nein zur Vorgesetztenstellung. Trenne Rang und Duty-Controller-Funktion und erläutere die belegte Befehlsweitergabe von Radtke.');
  if(!/radtke|weitergegeben|weitergeleitet|übermittel/.test(s))issues.push('Der Bezug zur belegten Befehlskette fehlt: Befehle Generalleutnant Radtkes wurden weitergegeben.');
 }
 if(id==='vorsitz'){
  if(/entscheidung (?:bleibt|liegt) bei (?:der )?strafkammer|publikum reflektiert die gesellschaftliche wahrnehmung|strafkammer trifft eine gesetzliche entscheidung/.test(s))issues.push('Falscher Stückablauf: Die Publikumsabstimmung bestimmt die verkündete Urteilsfassung. Nicht in eine unabhängige Gerichtsentscheidung plus blosse Publikumsreflexion umdeuten.');
  if(/publikum|schöff|zuschau|abstimm|eigene entscheidung/.test(q)&&(!/publikum|schöff|zuschau|abstimm/.test(s)||!/urteil|ausgang|freispruch|verurteil|endfassung/.test(s)||!/bestimm|entscheid|stimm|wähl|maßgeb|massgeb|ergebnis/.test(s)))issues.push('Die konkrete Funktion des Publikums fehlt: Seine Abstimmung bestimmt Freispruch oder Verurteilung; der Vorsitzende verkündet das Ergebnis.');
  if(/keine (?:weitere|zweite|andere) (?:text)?fassung|ohne eine weitere fassung/.test(s))issues.push('Die zweite Textfassung existiert. Trenne zwei alternative Fassungen im Stück von der einen pro Aufführung gewählten Fassung; keine Fassung nachträglich verneinen.');
  if(/fassung|freispruch|verurteil|ende/.test(q)&&!/freispruch/.test(s))issues.push('Freispruch als eine der beiden alternativen Fassungen fehlt.');
  if(/fassung|freispruch|verurteil|ende/.test(q)&&!/verurteil/.test(s))issues.push('Verurteilung als zweite alternative Fassung fehlt.');
 }
 return issues;
}
